script:
const q = (s) => element.querySelector(s);
const range = q('.flight-progress-input');
const track = q('.flight-track');
const mover = q('.flight-plane-mover');
const plane = q('.flight-plane');
const fill = q('.flight-track-fill');
const hours = q('.flight-countdown-hours');
const tensReel = q('.flight-reel-tens');
const strips = [q('.flight-reel-tens .flight-reel-strip'), q('.flight-reel-ones .flight-reel-strip')];
const label = q('.flight-arrival-label');
const countdown = q('.flight-countdown');
const spoken = q('.flight-countdown-text');
const toggle = q('.flight-playback');
const iconPause = q('.flight-icon-pause');
const iconPlay = q('.flight-icon-play');

const css = getComputedStyle(element);
const token = (n) => css.getPropertyValue(n).trim();
const msOf = (n) => parseFloat(token(n)) || 0;
const THROW = msOf('--flight-duration-throw');
const ROLL = msOf('--flight-duration-roll');
const MINUTE = msOf('--flight-duration-minute');
const EASE = token('--flight-ease-out');
const TOTAL = Number(range.max);
const START = Number(range.value);
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const show = (el, on, display = 'block') => { el.style.display = on ? display : 'none'; };

strips.forEach((s) => { s.style.transition = reduce ? 'none' : `transform ${ROLL}ms ${EASE}`; });
plane.style.transition = reduce ? 'none' : `transform ${ROLL}ms ${EASE}`;

let elapsed = START;
let playing = !reduce;
let timer = 0;
let frame = 0;

// While playing, each minute glides linearly into the next so the plane never stops.
function setGlide(ms) {
  mover.style.transition = ms ? `transform ${ms}ms linear` : 'none';
  fill.style.transition = ms ? `clip-path ${ms}ms linear` : 'none';
}

function render(value) {
  const p = Math.min(Math.max(value / TOTAL, 0), 1);
  const width = track.clientWidth;
  const size = plane.offsetWidth;
  mover.style.transform = `translateX(${(p * 100).toFixed(3)}%)`;
  const right = Math.max(width - (p * (width - size) + size / 2), 0);
  fill.style.clipPath = `inset(0 ${right.toFixed(2)}px 0 0 round var(--flight-radius-track))`;

  const left = Math.max(TOTAL - Math.round(value), 0);
  const h = Math.floor(left / 60);
  const m = left % 60;
  hours.textContent = `${h}h`;
  show(hours, h > 0);
  show(tensReel, h > 0 || m >= 10);
  strips[0].style.transform = `translateY(calc(${-Math.floor(m / 10)} * var(--flight-label-line)))`;
  strips[1].style.transform = `translateY(calc(${-(m % 10)} * var(--flight-label-line)))`;

  const landed = left === 0;
  label.textContent = landed ? 'Landed in Chennai' : 'Arrives in';
  show(countdown, !landed, 'inline-flex');
  const words = landed
    ? 'Landed in Chennai'
    : `${h ? `${h} hour${h === 1 ? '' : 's'} ` : ''}${m} minute${m === 1 ? '' : 's'} until arrival in Chennai`;
  spoken.textContent = words;
  range.value = String(Math.round(value));
  range.setAttribute('aria-valuetext', words);
}

function setIcons(next) {
  show(iconPause, next);
  show(iconPlay, !next);
  toggle.setAttribute('aria-label', next ? 'Pause flight playback' : 'Play flight playback');
}

function run() {
  setGlide(MINUTE);
  timer = setInterval(tick, MINUTE);
}

function setPlaying(next) {
  playing = next;
  clearInterval(timer);
  clearTimeout(timer);
  cancelAnimationFrame(frame);
  setIcons(next);
  if (!next) { setGlide(0); return; }
  if (elapsed >= TOTAL) throwPlane(0, START);
  else run();
}

function tick() {
  elapsed = Math.min(elapsed + 1, TOTAL);
  render(elapsed);
  if (elapsed < TOTAL) return;
  clearInterval(timer);
  timer = setTimeout(() => { if (playing) throwPlane(0, START); }, MINUTE * 4);
}

// The throw: the plane leaves the origin and decelerates onto its current
// position while the countdown rolls down to the time left.
function throwPlane(from, to) {
  clearInterval(timer);
  cancelAnimationFrame(frame);
  setGlide(0);
  const begin = performance.now();
  const step = (now) => {
    const t = Math.min((now - begin) / THROW, 1);
    elapsed = from + (to - from) * (1 - Math.pow(1 - t, 4));
    render(elapsed);
    if (t < 1) { frame = requestAnimationFrame(step); return; }
    elapsed = to;
    if (playing) run();
  };
  frame = requestAnimationFrame(step);
}

range.addEventListener('input', () => {
  if (playing) setPlaying(false);
  elapsed = Number(range.value);
  render(elapsed);
});
range.addEventListener('focus', () => {
  if (range.matches(':focus-visible')) track.style.boxShadow = 'var(--flight-focus-ring)';
});
range.addEventListener('blur', () => { track.style.boxShadow = 'none'; });
range.addEventListener('pointerenter', () => { plane.style.transform = 'scale(1.1)'; });
range.addEventListener('pointerleave', () => { plane.style.transform = 'none'; });
toggle.addEventListener('click', () => setPlaying(!playing));

render(START);
setIcons(playing);
if (playing) throwPlane(0, START);
